        .main-page {
            padding: 60px 0;
        }

        .tab {
            width: 100%;
            display: block;
            margin: 0 auto;
            text-align: center;
        }

        .tab ul.catedgory-list {
            list-style: none;
            margin: 0;
            padding: 0;
        }

        .tab ul.catedgory-list li {
            display: inline-block;
            margin: 15px auto;
        }

        .tab ul.catedgory-list li.active a {
            color: #fff;
            font-size: 16px;
            padding: 10px 60px;
            border: 2px solid #333;
            background: #333;
            margin: 0 5px;
        }

        .tab ul.catedgory-list li a {
            color: #333;
            font-size: 16px;
            padding: 10px 60px;
            border: 2px solid #333;
            margin: 0 5px;
            line-height: 16px;
        }

        .search {
            max-width: 70%;
            display: block;
            margin: 10px auto;
            text-align: center;
        }

        .search ul.alphabit-list {
            list-style: none;
            margin: 0;
            padding: 0;
            border: 1px solid #333;
            display: inline-block;
            float: left;
    margin-bottom: 20px;
        }

        .search ul.alphabit-list li {
            display: inline-block;
            margin: 5px auto;
        }

        .search ul.alphabit-list li a {
            color: #333;
            font-size: 16px;
            padding: 4px;
            margin: 0 2px;
            line-height: 16px;
        }
.search ul.alphabit-list li a:hover {color: blue;} 
       .search ul.alphabit-list li.active a {
            color: #000;
        }

        .boxes {
            width: 100%;
            clear: both;
            margin-top: 50px;
        }

        .boxes ul.post-list {
            list-style: none;
            margin: 0;
            padding: 0;
        }

        .boxes ul.post-list li {
            display: inline-block;
            margin: 12px;
            background: #fff;
            width: 31%;
            overflow: hidden;
            height: 420px;
            float: left;
        }

        .boxes ul.post-list li img {
            height: 235px;
            display: block;
        }

        .boxes .post-list .post-content h3 {
            font-family: 'GillSans-Medium';
            font-size: 24px;
            color: #000;
            padding:0px;
        }

        .boxes .post-list .post-content  p {
            font-family: 'GillSans-Medium';
            font-size: 14px;
            color: #636363;
            padding: 0px;
            display: block;
        }

        .boxes .place {
            padding-top: 15px;
        }

        .boxes li .first-para {
            padding: 30px 0 0 30px;
        }

        .boxes li br {
            display: none !important;
        }
        .post-cats {
            width: 100%;
            float: left;
            padding: 0 !important;
            margin: 7px 0 ;
        }
        ul.post-list .post-content {display: block;padding: 0px 27px;}
        ul.post-list h1 {
            font-size: 26px;
            line-height: 32px;
            width: 100%;
            float: left;
        }
        ul.post-list .post-cats li {
            width: auto !important;
            display: inline-block !important;
            height: auto;
            margin: 0;
            display: inline-block;
        }
        .post-image {
    height: 225px;
    overflow: hidden;
    background-size: cover;
    background-position: 100%;
}
        .no-result-div {
            text-align: center;
        }
.show-search-input {
    font-size: 16px;
    background: #333;
    color: #fff;
    border: none;
    padding: 6px 63px;
    display: inline-block;
    float: left;
}
.clear-filter{
    font-size: 16px;
    background: #333;
    color: #fff;
    border: none;
    padding: 6px 35px;
    display: inline-block;
    float: left;
}
.search-input-div {
    margin-top: 20px;
}
input.search-input {
    background: transparent;
    color: #fff;
    font-size: 16px;
    border: 1px solid #333;
    padding: 9px;
    max-width: 79%;
    width: 100%;
    float: left;
}
.search-input { display: none;}
.page-template-directory .boxes ul.post-list li .post-cats li {position: relative;padding-right: 15px;}
.page-template-directory .boxes ul.post-list li .post-cats li:after{position: absolute; content: "+"; top:1px; right: 3px; }
.page-template-directory .boxes ul.post-list li .post-cats li:last-child::after {display: none;}
.tab ul.catedgory-list li a:hover,.tab ul.catedgory-list li a:active,.tab ul.catedgory-list li a:focus { color: #fff; background: #333}
.show-search-input:hover,.clear-filter:hover{ color: #fff; }
@media only screen and (max-width: 600px) { 
.boxes ul.post-list li { width: 100%; margin: 10px 0; }
.show-search-input {margin: 0 auto 15px;
    display: block;width: 100%;
    box-sizing: border-box;
    text-align: center;}
    .clear-filter {float: unset;}
    .tab ul.catedgory-list li a,.tab ul.catedgory-list li {display: block;}
    input.search-input {max-width: 100%; margin:10px auto!important; }
}









